import { test, expect } from '@playwright/test';

test.describe('File Upload - Organize into Folders', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully upload a file and organize it into a specified folder', async ({ page }) => {
    // Intercept the file upload API
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Locate and click the file input using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Locate and select a file using getByLabel
    const fileSelect = page.getByLabel(/select file/i);
    await fileSelect.setInputFiles('fixtures/sample-file.pdf');

    // Locate and click the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for the upload to complete
    await page.waitForURL('**/api/upload/.*');

    // Verify success message using getByRole
    const successMessage = page.getByRole('status');
    await expect(successMessage).toContainText('File uploaded successfully');

    // Verify file appears in the specified folder using getByRole
    const folderList = page.getByRole('list', { name: /uploads/i });
    await expect(folderList).toBeVisible();

    const folderItem = page.getByText('Documents');
    await expect(folderItem).toBeVisible();

    // Verify file name is displayed
    const fileName = page.getByText('sample-file.pdf');
    await expect(fileName).toBeVisible();
  });

  test('should handle uploading multiple files into a single folder', async ({ page }) => {
    // Intercept the file upload API
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Locate and click the file input using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Locate and select multiple files using getByLabel
    const fileSelect = page.getByLabel(/select file/i);
    await fileSelect.setInputFiles('fixtures/sample-file1.pdf', 'fixtures/sample-file2.pdf');

    // Locate and click the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for the upload to complete
    await page.waitForURL('**/api/upload/.*');

    // Verify success message using getByRole
    const successMessage = page.getByRole('status');
    await expect(successMessage).toContainText('Files uploaded successfully');

    // Verify all files appear in the specified folder using getByRole
    const folderList = page.getByRole('list', { name: /uploads/i });
    await expect(folderList).toBeVisible();

    const folderItem = page.getByText('Documents');
    await expect(folderItem).toBeVisible();

    // Verify file names are displayed
    const fileName1 = page.getByText('sample-file1.pdf');
    await expect(fileName1).toBeVisible();
    const fileName2 = page.getByText('sample-file2.pdf');
    await expect(fileName2).toBeVisible();
  });
});
